<?php
namespace App\Policies; use App\Domain\Workplan\Models\WorkplanProgressReport; use App\Models\User;
class WorkplanProgressReportPolicy { public function viewAny(User $u):bool{return $u->can('view-workplans');} private function access(User $u,WorkplanProgressReport $r,string $p):bool{return $u->can($p)&&$u->canAccessMda($r->mda_id)&&($r->activity->department_id===null||$u->canAccessDepartment($r->activity->department_id));} public function view(User $u,WorkplanProgressReport $r):bool{return $this->access($u,$r,'view-workplans');} public function update(User $u,WorkplanProgressReport $r):bool{return $this->access($u,$r,'update-workplan-progress');} public function submit(User $u,WorkplanProgressReport $r):bool{return $this->update($u,$r);} public function verify(User $u,WorkplanProgressReport $r):bool{return $this->access($u,$r,'verify-workplan-progress');} public function return(User $u,WorkplanProgressReport $r):bool{return $this->verify($u,$r);} }
